
(function(){
  /* Lojas participantes: lista única em lojas.js (a mesma usada pelo servidor). */
  var LOJAS=window.EDC_LOJAS||{};
  /* WhatsApp do vendedor (botão "Finalize a compra com vendedor"): 47 99915-1352 */
  var WA_VENDEDOR='5547999151352';
  var ORIGEM_ENTRADA='LP + Agendamento',TAG_ORIGEM='PAG+AGENDAMENTO';
  /* Leads ficam no Supabase (tabela leads_site). Chave pública: só permite gravar; ler exige a senha da página de leads. */
  var SB_URL='https://lknyabeytbogmnfmnfpl.supabase.co',SB_KEY='sb_publishable_BxoXf3yXNVkAFfOnJUKBHA_UVn_wl3W';
  var CHAVE='edc_pag_agendamento_v1',VALIDADE=7*24*3600*1000;
  var UTM_KEYS=['utm_source','utm_medium','utm_campaign','utm_content','utm_term'];
  var HERO='data:image/webp;base64,';(new Image()).src=HERO;
  var WA_SVG='<svg viewBox="0 0 448 512" aria-hidden="true"><path d="M380.9 97.1C339 55.1 283.2 32 223.9 32c-122.4 0-222 99.6-222 222 0 39.1 10.2 77.3 29.6 111L0 480l117.7-30.9c32.4 17.7 68.9 27 106.1 27h.1c122.3 0 224.1-99.6 224.1-222 0-59.3-25.2-115-67.1-157zm-157 341.6c-33.2 0-65.7-8.9-94-25.7l-6.7-4-69.8 18.3L72 359.2l-4.4-7c-18.5-29.4-28.2-63.3-28.2-98.2 0-101.7 82.8-184.5 184.6-184.5 49.3 0 95.6 19.2 130.4 54.1 34.8 34.9 56.2 81.2 56.1 130.5 0 101.8-84.9 184.6-186.6 184.6zm101.2-138.2c-5.5-2.8-32.8-16.2-37.9-18-5.1-1.9-8.8-2.8-12.5 2.8-3.7 5.6-14.3 18-17.6 21.8-3.2 3.7-6.5 4.2-12 1.4-32.6-16.3-54-29.1-75.5-66-5.7-9.8 5.7-9.1 16.3-30.3 1.8-3.7.9-6.9-.5-9.7-1.4-2.8-12.5-30.1-17.1-41.2-4.5-10.8-9.1-9.3-12.5-9.5-3.2-.2-6.9-.2-10.6-.2-3.7 0-9.7 1.4-14.8 6.9-5.1 5.6-19.4 19-19.4 46.3 0 27.3 19.9 53.7 22.6 57.4 2.8 3.7 39.1 59.7 94.8 83.8 35.2 15.2 49 16.5 66.6 13.9 10.7-1.6 32.8-13.4 37.4-26.4 4.6-13 4.6-24.1 3.2-26.4-1.3-2.5-5-3.9-10.5-6.6z"></path></svg>';

  function dig(s){return String(s||'').replace(/\D/g,'');}
  /* Guarda a submissão no navegador (e em memória, se o armazenamento estiver bloqueado) */
  var MEM=null;
  function lerSub(){try{var v=localStorage.getItem(CHAVE);if(v)return JSON.parse(v);}catch(e){}return MEM?JSON.parse(MEM):null;}
  function gravarSub(s){MEM=JSON.stringify(s);try{localStorage.setItem(CHAVE,MEM);}catch(e){}}
  function apagarSub(){MEM=null;try{localStorage.removeItem(CHAVE);}catch(e){}}
  function uuid(){
    if(window.crypto&&crypto.randomUUID)return crypto.randomUUID();
    var b=new Uint8Array(16);crypto.getRandomValues(b);b[6]=(b[6]&15)|64;b[8]=(b[8]&63)|128;
    var h=[].map.call(b,function(x){return (x+256).toString(16).slice(1);}).join('');
    return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);
  }
  function agoraComFuso(){
    var d=new Date(),o=-d.getTimezoneOffset(),s=o>=0?'+':'-',a=Math.abs(o);
    function p(n){return (n<10?'0':'')+n;}
    return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds())+s+p(Math.floor(a/60))+':'+p(a%60);
  }
  /* UTMs: guarda o primeiro valor recebido nesta sessão para não perder ao navegar entre páginas */
  function lerUtms(){
    var q=new URLSearchParams(location.search),u={};
    UTM_KEYS.forEach(function(k){
      var v=q.get(k);
      try{ if(v){sessionStorage.setItem('edc_'+k,v);} else {v=sessionStorage.getItem('edc_'+k);} }catch(e){}
      u[k]=(v||'').slice(0,200);
    });
    return u;
  }
  lerUtms();

  /* ---------- Envio do cadastro (com reenvio usando o mesmo external_id) ---------- */
  var emVoo=false,timerReenvio=null,ESPERAS=[3000,10000,30000,60000];
  function enviarCadastro(){
    var sub=lerSub();
    if(!sub||sub.enviado||sub.invalido||emVoo)return;
    emVoo=true;clearTimeout(timerReenvio);
    sub.tentativas=(sub.tentativas||0)+1;gravarSub(sub);
    fetch(SB_URL+'/rest/v1/leads_site',{method:'POST',headers:{'Content-Type':'application/json','apikey':SB_KEY,'Prefer':'return=minimal'},body:JSON.stringify(sub.payload),keepalive:true,credentials:'omit'})
      .then(function(r){
        var s=lerSub();if(!s||s.payload.external_id!==sub.payload.external_id)return;
        /* 201 = salvo; 409 = já estava salvo (mesmo external_id) */
        if(r.ok||r.status===409){s.enviado=true;s.enviado_em=new Date().toISOString();delete s.payload.cpf;gravarSub(s);return;}
        if(r.status===400){s.invalido=true;gravarSub(s);return;}
        agendarReenvio(s);
      })
      .then(atualizarEstado,atualizarEstado)
      .catch(function(){var s=lerSub();if(s)agendarReenvio(s);atualizarEstado();})
      .then(function(){emVoo=false;});
  }
  function agendarReenvio(s){
    var n=Math.min((s.tentativas||1)-1,ESPERAS.length-1);
    if((s.tentativas||0)>=8)return; /* tenta de novo na próxima visita à página */
    clearTimeout(timerReenvio);timerReenvio=setTimeout(enviarCadastro,ESPERAS[n]);
  }
  window.addEventListener('online',enviarCadastro);
  document.addEventListener('visibilitychange',function(){if(document.visibilityState==='visible')enviarCadastro();});

  /* Mostra na tela o estado real do registro, sem prometer o que não aconteceu */
  function atualizarEstado(){
    var el=document.querySelector('.pa-registro');if(!el)return;
    var s=lerSub();var t='';
    if(s&&s.invalido)t='Não foi possível registrar seus dados. Por favor, fale com a loja.';
    el.textContent=t;
    var m=document.querySelector('.pa-cal-msg[data-sem-agenda]');
    if(m)m.textContent='O WhatsApp da loja '+m.getAttribute('data-sem-agenda')+' ainda não está disponível.'+(s&&s.enviado?' Seus dados foram recebidos e nossa equipe entrará em contato.':'');
  }
  setInterval(atualizarEstado,4000);
  /* Cria a submissão ou reaproveita a mesma (mesmo nome, telefone e loja) */
  function registrarSubmissao(nomeV,telV,cpfV,loja){
    var tel='+55'+dig(telV),ant=lerSub();
    if(ant&&ant.payload&&!ant.invalido&&ant.payload.loja===loja&&ant.payload.telefone===tel&&String(ant.payload.nome).toLowerCase()===nomeV.toLowerCase()&&(ant.enviado||ant.payload.cpf===dig(cpfV))&&(Date.now()-ant.criado)<VALIDADE){
      return ant;
    }
    var u=lerUtms();
    var payload={
      external_id:'pag-agendamento:'+loja+':'+uuid(),
      nome:nomeV,
      telefone:tel,
      loja:loja,
      origem_entrada:ORIGEM_ENTRADA,
      tag_origem:TAG_ORIGEM,
      submitted_at:agoraComFuso(),
      utm_source:u.utm_source,utm_medium:u.utm_medium,utm_campaign:u.utm_campaign,utm_content:u.utm_content,utm_term:u.utm_term,
      cpf:dig(cpfV)
    };
    var s={payload:payload,criado:Date.now(),enviado:false,tentativas:0};
    gravarSub(s);return s;
  }

  /* ---------- Tela de pré-aprovação + botão do WhatsApp do vendedor ---------- */
  function fmtTel(t){var d=dig(t).replace(/^55/,'');return d.length>=10?'('+d.slice(0,2)+') '+d.slice(2,d.length-4)+'-'+d.slice(-4):t;}
  function mostrarAprovado(box,sub,retomada){
    var p=sub.payload,l=LOJAS[p.loja];
    box.innerHTML='<img class="pa-hero" src="'+HERO+'" alt="Atendente da Espaço do Celular comemorando"><div class="pa-step"><h2><span class="pa-nome"></span>Seu perfil foi <span style="white-space:nowrap">pré-aprovado!</span> 🎉</h2><p>Clique no botão abaixo e fale diretamente com um vendedor da nossa loja para conhecer as opções de pagamento e dar continuidade à sua compra.</p><a class="pa-submit pa-cta" target="_blank" rel="noopener"></a><p class="pa-cal-msg" role="status" aria-live="polite"></p><p class="pa-registro" role="status" aria-live="polite"></p></div>'+(retomada?'<a class="pa-back pa-nova" href="#">Não é você? Fazer uma nova pré-análise</a>':'');
    box.querySelector('.pa-nome').textContent=p.nome.replace(/\s+/g,' ');
    var a=box.querySelector('.pa-cta');
    a.innerHTML=WA_SVG+'FINALIZE A COMPRA COM VENDEDOR';
    if(false){
      a.removeAttribute('target');a.setAttribute('aria-disabled','true');a.classList.add('pa-sem-agenda');
      a.addEventListener('click',function(e){e.preventDefault();});
      box.querySelector('.pa-cal-msg').setAttribute('data-sem-agenda',l.nome);
    } else {
      /* Mensagem pronta para o vendedor: nome, telefone e loja. CPF NÃO vai no link do WhatsApp. */
      var texto='Olá! Vim pelo site e gostaria de conhecer as opções disponíveis para comprar meu celular novo.';
      a.href='https://wa.me/'+WA_VENDEDOR+'?text='+encodeURIComponent(texto);
      a.addEventListener('click',function(){try{(window.dataLayer=window.dataLayer||[]).push({event:'clique_whatsapp_vendedor',loja:p.loja});}catch(e){}});
    }
    atualizarEstado();
    var nova=box.querySelector('.pa-nova');
    if(nova)nova.addEventListener('click',function(e){e.preventDefault();apagarSub();location.href=location.pathname+(p.loja?'?loja='+p.loja:'');});
  }

  
  /* ---------- Modo da página: form (site), analise (processando), aprovado ---------- */
  var MODO=document.body.getAttribute('data-pa')||'form';

  /* ---------- Cliques nos botões de WhatsApp (contados na página de leads) ---------- */
  function visitanteId(){
    var k='edc_visitante',v=null;
    try{v=localStorage.getItem(k);}catch(e){}
    if(!v){v='v-'+uuid();try{localStorage.setItem(k,v);}catch(e){}}
    return v;
  }
  function registrarClique(botao,posicao){
    try{
      var u=lerUtms()||{},s=lerSub();
      var corpo={botao:botao,posicao:posicao||null,visitante:visitanteId(),
        external_id:(s&&s.payload&&s.payload.external_id)||null,
        utm_source:u.utm_source||null,utm_medium:u.utm_medium||null,utm_campaign:u.utm_campaign||null,utm_content:u.utm_content||null};
      fetch(SB_URL+'/rest/v1/cliques_whatsapp',{method:'POST',keepalive:true,credentials:'omit',
        headers:{'Content-Type':'application/json','apikey':SB_KEY,'Prefer':'return=minimal'},body:JSON.stringify(corpo)}).catch(function(){});
    }catch(e){}
  }
  document.addEventListener('click',function(e){
    var a=e.target&&e.target.closest?e.target.closest('a[href*="wa.me/"]'):null;
    if(!a)return;
    if(a.classList.contains('pa-cta')){registrarClique('finalizar_vendedor','pre-aprovado');return;}
    var todos=[].slice.call(document.querySelectorAll('a[href*="wa.me/"]:not(.pa-cta)'));
    var i=todos.indexOf(a);
    registrarClique('compre_whatsapp',i===0?'topo':i===todos.length-1?'final':'botao-'+(i+1));
  },true);

  var box=document.querySelector('.pa-box');
  /* Reserva: nome/telefone/loja vão no endereço caso o navegador bloqueie o armazenamento. CPF nunca vai no endereço. */
  function hashDe(s){var p=s.payload;return '#d='+encodeURIComponent(JSON.stringify({nome:p.nome,telefone:p.telefone,loja:p.loja}));}
  function subDoHash(){try{var m=location.hash.match(/d=([^&]+)/);if(!m)return null;var d=JSON.parse(decodeURIComponent(m[1]));if(!d||!d.nome||!LOJAS[d.loja])return null;return {payload:{nome:String(d.nome),telefone:String(d.telefone||''),loja:d.loja},criado:Date.now(),enviado:true};}catch(e){return null;}}
  function subValida(s){return s&&s.payload&&s.payload.nome&&LOJAS[s.payload.loja]?s:null;}
  function voltarAoForm(){location.replace('index.html#formulario');}

  if(MODO==='analise'){
    var sA=subValida(lerSub())||subDoHash();
    if(!sA){voltarAoForm();return;}
    enviarCadastro();
    box.innerHTML='<div class="pa-step"><div class="pa-spin"></div><h2>ANALISANDO SEUS DADOS</h2><p>Aguarde um instante, estamos verificando as condições disponíveis para você.</p><div class="pa-bar"><i></i></div><div class="pa-etapa">Analisando seu nome...</div><div class="pa-pct">0%</div></div>';
    var bar=box.querySelector('.pa-bar i'),pct=box.querySelector('.pa-pct'),etapa=box.querySelector('.pa-etapa'),ETAPAS=['Analisando seu nome...','Analisando CPF...','Analisando Telefone...'],T=3000,t0=performance.now();
    (function tick(now){var k=Math.max(0,Math.min(1,(now-t0)/T));bar.style.width=(k*100)+'%';pct.textContent=Math.floor(k*100)+'%';var et=ETAPAS[Math.min(2,Math.floor(k*3))];if(etapa.textContent!==et)etapa.textContent=et;
      if(k<1){requestAnimationFrame(tick);return;}
      location.replace('aprovado.html'+hashDe(sA));
    })(t0);
    return;
  }

  if(MODO==='aprovado'){
    var sB=subValida(lerSub())||subDoHash();
    if(!sB){voltarAoForm();return;}
    mostrarAprovado(box,sB,false);
    enviarCadastro();
    try{(window.dataLayer=window.dataLayer||[]).push({event:'pre_aprovado',loja:sB.payload.loja});}catch(e){}
    return;
  }

/* ---------- Formulário ---------- */
  /* Sem escolha de loja no formulário: usa a loja do link (?loja=) ou a loja padrão */
  var LOJA_PADRAO='itajai';
  var q=(new URLSearchParams(location.search).get('loja')||'').toLowerCase();
  var lojaEscolhida=LOJAS[q]?q:LOJA_PADRAO;
  var tel=document.getElementById('paTel'),cpf=document.getElementById('paCpf'),nome=document.getElementById('paNome');
  tel.addEventListener('input',function(){var d=dig(tel.value).slice(0,11),o='';if(d.length>0)o='('+d.slice(0,2);if(d.length>=3)o+=') '+d.slice(2,d.length>10?7:6);if(d.length>=(d.length>10?8:7))o+='-'+d.slice(d.length>10?7:6);tel.value=o;});
  cpf.addEventListener('input',function(){var d=dig(cpf.value).slice(0,11),o=d.slice(0,3);if(d.length>3)o+='.'+d.slice(3,6);if(d.length>6)o+='.'+d.slice(6,9);if(d.length>9)o+='-'+d.slice(9);cpf.value=o;});
  function cpfOk(c){c=dig(c);if(c.length!==11||/^(\d)\1+$/.test(c))return false;for(var t=9;t<11;t++){var s=0;for(var i=0;i<t;i++)s+=+c[i]*(t+1-i);if(((s*10)%11)%10!==+c[t])return false;}return true;}
  function mark(el,bad){el.classList.toggle('pa-bad',bad);el.parentNode.classList.toggle('has-err',bad);}
  [nome,tel,cpf].forEach(function(el){el.addEventListener('input',function(){mark(el,false);});});

  
  /* Cadastro pendente de outra visita: tenta enviar de novo */
  var salvo=lerSub();
  if(salvo&&(Date.now()-salvo.criado)>=VALIDADE&&salvo.enviado){apagarSub();}
  else if(salvo&&!salvo.enviado){enviarCadastro();}

  var enviando=false;
  var formEl=document.getElementById('paForm');
  if(formEl)formEl.addEventListener('submit',function(e){
    e.preventDefault();
    if(enviando)return;
    var b1=nome.value.trim().length<3,b2=dig(tel.value).length<10,b3=!cpfOk(cpf.value);
    mark(nome,b1);mark(tel,b2);mark(cpf,b3);
    if(b1||b2||b3){(b1?nome:b2?tel:cpf).focus();return;}
    enviando=true;
    var NOME=nome.value.trim().replace(/\s+/g,' ');
    var sub=registrarSubmissao(NOME,tel.value,cpf.value,lojaEscolhida);
    enviarCadastro();
    location.href='analise.html'+hashDe(sub);
  });
})();
